html { font-size: 16px; }

.box-px {
  width: 200px;       /* fixed, always 200px */
}

.box-percent {
  width: 50%;         /* 50% of parent width */
}

.box-em {
  font-size: 2em;     /* 2 x parent's font-size */
}

.box-rem {
  font-size: 2rem;    /* 2 x root (html) font-size = 32px */
}

.box-vh-vw {
  height: 100vh;      /* full viewport height */
  width: 50vw;        /* half viewport width */
}

/* Problem with em (compounding) */
.parent { font-size: 20px; }
.child { font-size: 1.5em; }   /* 20 x 1.5 = 30px */
.grandchild { font-size: 1.5em; } /* 30 x 1.5 = 45px (unexpected growth) */

/* Solution with rem (consistent) */
html { font-size: 16px; }
.child { font-size: 1.5rem; }      /* always 24px */
.grandchild { font-size: 1.5rem; } /* always 24px, no compounding */

/* Absolute unit — fixed, doesn't adapt */
.box-absolute {
  width: 300px;
  font-size: 16px;
}

/* Relative units — adapt based on context */
.box-relative {
  width: 80%;        /* relative to parent */
  font-size: 1.2rem; /* relative to root font-size */
  padding: 2vw;       /* relative to viewport width */
}
